        if self.potential_bags:
            chosen_bag = max(self.potential_bags, key=lambda x: x[1])[0]
            return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=chosen_bag, type='custom')])
