    for bag_index, value in guess_bag[-2:]:
        if bag_index in average_values and average_values[bag_index] == max(average_values.values()):
            if value < max(average_values.values()):  # prioritize highest if recent choices were lower
                previous_best_bag = bag_index
                break

    # If no previous best found, choose the bag with the highest remaining average
    if not previous_best_bag:
        best_bag_index = max(average_values, key=average_values.get)
        return best_bag_index
    else:
        # Balancing between recent choice and highest average value
        if previous_best_bag in average_values and average_values[previous_best_bag] > max(average_values.values()):
            return previous_best_bag
        else:
            best_bag_index = max(average_values, key=average_values.get)
